from scipy.sparse.linalg import eigs
from scipy.sparse.linalg._eigen.arpack.arpack import _UnsymmetricArpackParams
from scipy.sparse import _sparsetools
from reference import Task

task = Task()

def eigs_fn(A):
    N=A.shape[0]
    return eigs(A,k=5,v0=np.ones(N),maxiter=N*200,ncv=20)

def fast_st(A, copyx=True):
    n=A.shape[0]
    data = A.data
    indices = A.indices
    indptr = A.indptr
    y = np.empty(n, dtype=np.float64)
    if copyx:
        def matvec(x):
            xx = np.array(x, dtype=np.float64, copy=True)
            _sparsetools.csr_matvec(n, n, indptr, indices, data, xx, y)
            return y.copy()
    else:
        def matvec(x):
            _sparsetools.csr_matvec(n, n, indptr, indices, data, np.ascontiguousarray(x), y)
            return y.copy()
    params = _UnsymmetricArpackParams(n,5,'d',matvec,ncv=20,v0=np.ones(n),maxiter=n*200,which='LM',tol=0)
    while not params.converged:
        params.iterate()
    return params.extract(True)

def bench(fn, nseed=6):
    tot=0
    for seed in range(nseed):
        A=task.generate_problem(n=300, random_seed=seed)["matrix"]
        t0=time.perf_counter(); fn(A); tot+=time.perf_counter()-t0
    return tot

print("eigs", bench(eigs_fn))
print("st", bench(lambda A: fast_st(A, True)))
print("st2", bench(lambda A: fast_st(A, False)))

for seed in range(6):
    A=task.generate_problem(n=300, random_seed=seed)["matrix"]
    ev1,V1=eigs_fn(A)
    for name,c in [("copy",True),("nocopy",False)]:
        ev2,V2=fast_st(A,c)
        o1=np.argsort(-np.abs(ev1)); o2=np.argsort(-np.abs(ev2))
        sims=[abs(np.vdot(V1[:,i],V2[:,j]))/(np.linalg.norm(V1[:,i])*np.linalg.norm(V2[:,j])) for i,j in zip(o1,o2)]
        print(name, seed, round(min(sims),6), round(float(np.max(np.abs(np.sort_complex(ev1)-np.sort_complex(ev2)))),12))
