import numpy as np
from scipy.sparse.linalg._eigen.arpack.arpack import _UnsymmetricArpackParams
from scipy.sparse import _sparsetools
from reference import Task

task=Task(); A=task.generate_problem(n=300, random_seed=0)["matrix"]
n=A.shape[0]

def run(label, matvec):
    params = _UnsymmetricArpackParams(n,5,'d',matvec,ncv=20,v0=np.ones(n),maxiter=n*200,which='LM',tol=0)
    c=0
    try:
        while not params.converged:
            params.iterate(); c+=1
        print(label, "converged iters", c, "nconv", params.arpack_dict['nconv'])
        return params.extract(True)
    except Exception as e:
        print(label, "FAIL after", c, type(e).__name__, str(e)[:150])
        return None

def mv_dot(x):
    return A.dot(np.array(x, copy=True))
def mv_st(x):
    xx=np.array(x, dtype=np.float64, copy=True)
    y=np.empty(n)
    _sparsetools.csr_matvec(n,n,A.indptr,A.indices,A.data,xx,y)
    return y
def mv_st_inplace_y_copy(x):
    # reuse y buffer but return copy
    y = mv_st_inplace_y_copy.y
    xx=np.array(x, dtype=np.float64, copy=True)
    _sparsetools.csr_matvec(n,n,A.indptr,A.indices,A.data,xx,y)
    return y.copy()
mv_st_inplace_y_copy.y=np.empty(n)

def mv_matmul(x):
    return A._matmul_vector(x)

evs={}
for name, fn in [("dot", mv_dot), ("st", mv_st), ("st_ycopy", mv_st_inplace_y_copy), ("matmul", mv_matmul)]:
    evs[name]=run(name, fn)

from scipy.sparse.linalg import eigs
ev1,V1=eigs(A,k=5,v0=np.ones(n),maxiter=n*200,ncv=20)
print("eigs evals", np.sort_complex(ev1))
for name, res in evs.items():
    if res is None: continue
    ev,V=res
    print(name, "eval diff", np.max(np.abs(np.sort_complex(ev)-np.sort_complex(ev1))))
