        int ido=st.ido;
        if(ido==1 || ido==2 || ido==5){
            int x0 = ipntr[0]-1; /* ARPACK ipntr is 1-based? check */
            int y0 = ipntr[1]-1;
            /* try both conventions: print first step */
            if(steps<=2){
                printf("step %d ido=%d ipntr:", steps, ido);
                for(int i=0;i<14;i++) printf(" %d", ipntr[i]);
                printf("\ninfo=%d\n", st.info);
            }
            /* assume 1-based like classic ARPACK */
            if(x0<0 || y0<0 || x0+n>3*n || y0+n>3*n){
                /* maybe 0-based */
                x0 = ipntr[0]; y0 = ipntr[1];
            }
            for(int i=0;i<n;i++){
                workd[y0+i] = (i+1) * workd[x0+i];
            }
        } else if(ido==4){
            for(int i=0;i<n;i++) resid[i]=1.0;
        } else {
            printf("done steps=%d ido=%d info=%d nconv=%d iter=%d\n", steps, ido, st.info, st.nconv, st.iter);
            break;
        }
    }
