    double d[6];
    int32_t i[36];
} state_t;

static void handler(int sig){ fprintf(stderr,"SIG %d\n",sig); _exit(2); }
typedef void (*fn_t)();

static void csr_mv(int n, const int32_t* indptr, const int32_t* indices, const double* data,
                   const double* x, double* y){
    for(int i=0;i<n;i++){
        double s=0;
        int a=indptr[i], b=indptr[i+1];
        for(int j=a;j<b;j++) s += data[j]*x[indices[j]];
        y[i]=s;
    }
}

int main(){
