    void* h = dlopen("/Users/mark/Desktop/AI/Pivotal/.venv/lib/python3.11/site-packages/scipy/sparse/linalg/_eigen/arpack/_arpacklib.cpython-311-darwin.so", RTLD_NOW);
    fn_t fn = (fn_t)dlsym(h, "ARNAUD_dnaupd");

    /* diagonal matrix 1..6 */
    int n=6, ncv=4, nev=2;
    int32_t indptr[7]; int32_t indices[6]; double data[6];
    for(int i=0;i<6;i++){ indptr[i]=i; indices[i]=i; data[i]=i+1; }
    indptr[6]=6;

    state_t st; memset(&st,0,sizeof(st));
    st.i[2]=1; st.i[4]=1; st.i[5]=n; st.i[6]=ncv; st.i[7]=nev; st.i[8]=1; st.i[9]=300;
    double resid[6]; for(int i=0;i<6;i++) resid[i]=1.0;
    double *v = calloc(n*(size_t)ncv,8);
    int32_t ipntr[14]; memset(ipntr,0,sizeof(ipntr));
    double *workd = calloc(3*(size_t)n,8);
    double *workl = calloc(3*(size_t)ncv*(ncv+2),8);

    int steps=0;
    while(steps<100000){
        fn(&st, resid, v, ipntr, workd, workl);
        steps++;
        int ido = st.i[1];
        if(steps<=3){
            printf("step %d ido=%d info=%d ipntr:", steps, ido, st.i[2]);
            for(int k=0;k<6;k++) printf(" %d", ipntr[k]);
            printf("\n"); fflush(stdout);
        }
        if(ido==1 || ido==2 || ido==5){
            int x0=ipntr[0]-1, y0=ipntr[1]-1;
            if(x0<0||y0<0){ fprintf(stderr,"bad ptr %d %d\n", ipntr[0], ipntr[1]); return 3; }
            csr_mv(n, indptr, indices, data, workd+x0, workd+y0);
        } else if(ido==4){
            for(int i=0;i<n;i++) resid[i]=1.0;
        } else {
            printf("done steps=%d ido=%d info=%d nconv=%d iter=%d\n", steps, ido, st.i[2], st.i[10], st.i[11]);
            break;
        }
    }
    return 0;
}
