    .text
    .globl _call_dnaupd
# void call_dnaupd(void* fn, state*, resid, v, ipntr, workd, workl)
# args: rdi=fn, rsi=state, rdx=resid, rcx=v, r8=ipntr, r9=workd, stack=workl
_call_dnaupd:
    pushq %rbp
    movq %rsp, %rbp
    pushq %rbx
    subq $8, %rsp          # wrapper does subq $8 before push
    movq %rdi, %rbx        # fn
    movq %rsi, %rdi        # state
    movq %rdx, %rsi        # resid
    movq %rcx, %rdx        # v
    movq %r8, %rcx         # ipntr
    movq %r9, %r8          # workd
    movq 16(%rbp), %r9     # workl (7th incoming arg at 16(%rbp))
    pushq %r9              # workl as stack arg
    callq *%rbx
    addq $16, %rsp
    popq %rbx
    popq %rbp
    ret
